SELECT c3 AS Title 
FROM w 
WHERE c1_number = (
    SELECT MAX(c1_number)
    FROM w
);

SELECT COUNT(*) 
FROM w 
WHERE c3_number > 50;

SELECT c6 
FROM w 
WHERE c1 = 14;

SELECT c4 
FROM w 
WHERE c2 = 'green bay packers';

SELECT count(*)
FROM w
WHERE c3 LIKE '%usain bolt%' AND c5 = 'beijing, china';

SELECT *
FROM w 
WHERE c4 LIKE '%Russia%';

SELECT DISTINCT c2_number 
FROM w 
WHERE c4_first_number > 50;

SELECT c7_number 
FROM w 
WHERE c3_raw = 'philadelphia eagles';

SELECT c3 
FROM w
WHERE LOWER(c2) = 'vanscoy no. 345';

SELECT AVG(c6_number) as average_intake 
FROM w 
WHERE c7_number < 2100;

SELECT MAX(c6_number) AS max_caps 
FROM w 
WHERE c5 = 'england';

SELECT w.c3, w.c4 
FROM w 
WHERE w.c1_number = 2013;

SELECT c2_number 
FROM w 
WHERE c1 = '1965';
